test('applies functions right-to-left', () => {
  const double = x => x * 2;
  const addOne = x => x + 1;
  expect(compose(double, addOne)(3)).toBe(8);
});

test('single function acts as identity wrapper', () => {
  const double = x => x * 2;
  expect(compose(double)(5)).toBe(10);
});

test('composes three functions', () => {
  const triple = x => x * 3;
  const addTwo = x => x + 2;
  const negate = x => -x;
  expect(compose(triple, addTwo, negate)(4)).toBe(-6);
});

test('rightmost function receives the initial value', () => {
  const calls = [];
  const tag = name => x => { calls.push(name); return x; };
  compose(tag('first'), tag('second'))(0);
  expect(calls).toEqual(['second', 'first']);
});

