test('works with string transforms', () => {
  const trim = s => s.trim();
  const upper = s => s.toUpperCase();
  expect(compose(trim, upper)('  hello  ')).toBe('HELLO');
});

solution:
export function compose(...fns) {
  return function(x) {
    return fns.reduceRight((acc, fn) => fn(acc), x);
  };
}
